css:
.loader {
  position: relative;
  width: 48px;
  height: 52px;
}
.loader i {
  position: absolute;
  left: 50%;
  border-radius: 50%;
  background: #6366f1;
  animation: swirl 1s ease-in-out infinite;
}
.loader i:nth-child(1) { top: 2px; width: 44px; height: 10px; margin-left: -22px; animation-delay: 0s; opacity: 0.9; }
.loader i:nth-child(2) { top: 16px; width: 32px; height: 9px; margin-left: -16px; animation-delay: 0.1s; opacity: 0.8; }
.loader i:nth-child(3) { top: 29px; width: 20px; height: 8px; margin-left: -10px; animation-delay: 0.2s; opacity: 0.7; }
.loader i:nth-child(4) { top: 41px; width: 10px; height: 7px; margin-left: -5px; animation-delay: 0.3s; opacity: 0.6; }
@keyframes swirl {
  0%, 100% { transform: translateX(-4px) scaleX(0.85); }
  50% { transform: translateX(4px) scaleX(1); }
}
